        "q": "Q34_TopWeightedCompletedWeaponOrdersByGuildPolicy",
        "label": "Top Weighted Completed Weapon Orders By Guild Policy",
        "sqlite": "5.55 ms",
        "cdb": "94.0 \u00b5s",
